const p = $('Extract Params').item.json;
// 防御: Set 节点可能把 links 数组序列化成字符串 "["..."]", 这里兼容两种
let links = p.links;
if (typeof links === 'string') {
  const t = links.trim();
  if (t.startsWith('[')) {
    try { links = JSON.parse(t); } catch(e) { links = [t]; }
  } else {
    links = [t];
  }
}
const arr = Array.isArray(links) ? links : [links].filter(Boolean);
if (arr.length === 0) throw new Error('No links provided');
return arr.map((url, i) => ({ json: { url, index: i + 1, total: arr.length } }));

const http = require('http');
function parseUrl(url) {
  const m = url.match(/^https?:\/\/([^:\/]+)(?::(\d+))?([^?]*)/);
  if (!m) throw new Error('bad url: ' + url);
  return { hostname: m[1], port: m[2] ? parseInt(m[2]) : 80, path: m[3] || '/' };
}
function request(opts, payload) {
  return new Promise((res, rej) => {
    const body = payload ? JSON.stringify(payload) : null;
    const headers = { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' };
    if (opts.session) headers['mcp-session-id'] = opts.session;
    if (body) headers['Content-Length'] = Buffer.byteLength(body);
    const req = http.request({ hostname: opts.hostname, port: opts.port, path: opts.path, method: opts.method, headers, timeout: opts.timeout || 60000 }, r => {
      let d = ''; r.on('data', c => d += c); r.on('end', () => {
        let jsonStr = d;
        const m = d.match(/^data: (.*)$/m);
        if (m) jsonStr = m[1];
        try { res({ status: r.statusCode, session: r.headers['mcp-session-id'], body: JSON.parse(jsonStr) }); }
        catch(e) { rej(new Error('bad mcp resp: ' + d.slice(0, 300))); }
      });
    });
    req.on('error', rej); req.on('timeout', () => { req.destroy(); rej(new Error('timeout')); });
    if (body) req.write(body);
    req.end();
  });
}

const url = $input.first().json.url;
const u = parseUrl('http://192.168.1.41:5556/mcp');

// 1. initialize (顶层 await)
const init = await request({ hostname: u.hostname, port: u.port, path: '/mcp', method: 'POST' }, {
  jsonrpc: '2.0', id: 0, method: 'initialize',
  params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'n8n-xhs', version: '1.0' } }
});
const session = init.session;
if (!session) throw new Error('no mcp-session-id from initialize');
// 2. tools/call
const call = await request({ hostname: u.hostname, port: u.port, path: '/mcp', method: 'POST', session }, {
  jsonrpc: '2.0', id: 1, method: 'tools/call',
  params: { name: 'get_detail_data', arguments: { url } }
});
const sc = (call.body && call.body.result && call.body.result.structuredContent) || {};
const raw = (call.body && call.body.result && call.body.result.content && call.body.result.content[0] && call.body.result.content[0].text) || '';
let data = null;
try { data = JSON.parse(raw).data; } catch(e) {}
return [{ json: { message: sc.message || '', data: data || {}, raw_mcp: raw.slice(0, 500) } }];

const rows = $input.all();
const notes = [];
for (const row of rows) {
  const d = row.json.data || {};
  if (!d['作品标题']) continue;
  notes.push({
    title: d['作品标题'] || '',
    desc: (d['作品描述'] || '').slice(0, 600),
    tags: (d['作品标签'] || '').split(/\s+/).filter(Boolean).slice(0, 10),
    likes: d['点赞数量'] || '',
    collects: d['收藏数量'] || '',
    comments: d['评论数量'] || '',
    author: d['作者昵称'] || '',
    type: d['作品类型'] || '',
    url: d['作品链接'] || ''
  });
}
const params = $('Extract Params').item.json;
return [{ json: { notes, theme: params.theme || '', num_images: params.num_images, tg_chat_id: params.tg_chat_id, tg_bot_token: params.tg_bot_token, drafts_root: params.drafts_root, cover_url: params.cover_url }}];

const p = $input.first().json;
// 跨节点引用 Extract Params (scene_plan/cover_indices 不在 Parse MCP Results 透传里, 坑15/16教训)
const ep = $('Extract Params').item.json;
const scenePlanRaw = (ep.scene_plan !== undefined && ep.scene_plan !== '') ? ep.scene_plan : (p.scene_plan || '');
const coverIdx = (ep.cover_indices && ep.cover_indices.length) ? ep.cover_indices : (p.cover_indices || [1]);
const notes = p.notes || [];
const samplesText = notes.map((n, i) => `热度样本${i+1}【${n.author}】${n.title}\n(赞${n.likes} 藏${n.collects} 评${n.comments})\n正文摘要: ${n.desc.slice(0, 300)}\n标签: ${n.tags.join(' ')}`).join('\n\n---\n\n');

const sysPrompt = `你是专业的小红书爆款文案师, 账号定位为家居装修干货号「宅有宅的道理」。严格遵守: (1) 标题15字内, 带emoji, 有钩子, 有代入感, 格式参考「XX | 元素1+元素2+元素3, 情感句」; (2) 正文250-600字, 短句多段, emoji点缀, 有场景感, 干货密度高, 可直接照做; (3) 结尾3-5个疑问句或CTA, 但禁止诱导互动(禁「评论区扣XX领资料」「私信领包」等); (4) 8-10个中文tag; (5) ${p.num_images}张配图的英文prompt, 每张60词内, 描述具体场景+光线+构图, 覆盖不同角度/景别; (6) 配图场景按主题自动判断: 施工/水电/硬装/改造过程类主题→真实装修现场(毛坯墙/开槽/管线/工具/材料, 干净利落), 严格禁止摆放成品家具(沙发/电视柜/床/窗帘等), 因为现场还未完工; 风格/软装/完工效果类主题→成品效果图(带完整家具+软装+灯光氛围); (7) 所有image_prompt严格禁止出现任何文字、字母、标签、表格、印刷品、logo、水印(尤其禁止英文字母/英文单词), 只描述场景/物体/光线/构图; 严禁画尺寸标注(如1.3m/0.3m)、严禁画带字的便签/标签/清单纸/图纸/刻度尺/包装说明, 这些必然渲染出文字乱码, 一律用无字的实物代替(如纯色胶带/空白便利贴/留白); (8) 若配图中出现人物, 一律为中国人/东亚人(中国装修工人/中国屋主), 严禁外国人/白人/黑人或洋人面孔; (9) 第1张配图(封面图)必须强冲击力抓眼球: 大场景/强透视/高对比光线/色彩鲜明, 一眼抓住注意力, 适合做小红书封面.

**去AI味/增人味**: 像真人装修过、踩过坑的屋主在分享, 不要像AI客服或营销号。避免「首先/其次/总而言之/值得注意的是/让我们」等AI腔词; 避免过度工整的排比句; 多用口语、具体场景细节、真实踩坑/翻车经历、价格和尺寸等实在信息; emoji 克制使用不堆砌; 语气像跟朋友安利, 不是播报新闻.

**严格禁止**: 正文body里不允许出现以 # 开头的行或裸tag, tag只在返回JSON的tags数组里, 不许在body里重复; 不许把tags再以 ## 双井号形式重复输出.

严格返回JSON: {"title":"...", "body":"...", "tags":["tag1",...共8-10个], "image_prompts":["en1",...共${p.num_images}个]}`;

const theme = p.theme ? p.theme.trim() : '';
const userPrompt = theme ? `下面是小红书热榜/高赞笔记的真实数据(仅作爆款结构参考: 标题钩子/情绪/干货密度):

${samplesText}

请围绕指定主题创作一篇属于「宅有宅的道理」账号的全新装修干货笔记:
【指定主题】${theme}

创作要求:
1. 严格围绕「${theme}」展开, 这是装修/软装/改造相关主题, 属于账号垂类。
2. 内容必须干货可照做: 具体到产品型号、尺寸、安装位置、布线/布局逻辑、预算、避坑点等, 教用户怎么做这件事。
3. 从上面热榜笔记提炼爆款结构(标题钩子/情绪节奏/干货密度/互动提问)移植到本主题, 但不照搬原文。
4. 动笔前自检: 能否用一句话说清「教用户怎么做${theme}」? 能, 才动笔。
5. 根据主题判断配图场景: 施工/水电/硬装/改造过程类→真实装修现场(禁成品家具); 风格/软装/完工效果类→成品效果图(带完整家具软装)。6. 所有image_prompt严格禁止文字/字母/标签/表格/印刷品/logo/水印(尤其禁英文); 严禁画尺寸标注、带字的便签/清单纸/图纸/刻度尺(必出乱码), 用无字实物代替。7. 人物一律中国人/东亚人(中国工人/屋主), 严禁外国人面孔。7. 像真人屋主分享, 去AI味增人味(见system要求)。` : `下面是小红书热榜/高赞笔记的真实数据, 请提炼这些内容的爆款共性(主题方向、情绪钩子、干货结构), 并创作一篇属于「宅有宅的道理」账号的全新装修干货笔记(可迭代升级选题, 不要照抄原文):

${samplesText}

创作要求:
1. 严格围绕「装修/软装/收纳/改造」这一账号垂类创作, 禁止跨界到美妆/母婴/数码/穿搭/美食等其他垂类。
2. 动笔前先自检: 这篇笔记能否用一句话说清「教用户怎么做某件装修/软装/收纳的事」? 能, 才动笔。
3. 如果热榜内容与装修无关, 提炼其爆款结构(标题钩子/情绪/干货密度)移植到装修题材上, 而不是照搬主题。
4. 根据笔记主题判断配图场景: 施工/水电/硬装/改造过程类→真实装修现场(禁成品家具); 风格/软装/完工效果类→成品效果图(带完整家具软装)。5. 所有image_prompt严格禁止文字/字母/标签/表格/印刷品/logo/水印(尤其禁英文); 严禁画尺寸标注、带字的便签/清单纸/图纸/刻度尺(必出乱码), 用无字实物代替。6. 人物一律中国人/东亚人(中国工人/屋主), 严禁外国人面孔。6. 像真人屋主分享, 去AI味增人味(见system要求)。`;

// ===== scene_plan 支持: 解析方案, 配图数量/风格由方案决定 =====
let scenePlan = null;
if (scenePlanRaw && typeof scenePlanRaw === 'string') {
  try { scenePlan = JSON.parse(scenePlanRaw); } catch(e) { console.log('scene_plan parse err', e.message); }
} else if (scenePlanRaw && typeof scenePlanRaw === 'object') {
  scenePlan = scenePlanRaw;
}
const sceneCount = (scenePlan && Array.isArray(scenePlan.images)) ? scenePlan.images.length : 0;
const effNum = sceneCount > 0 ? sceneCount : p.num_images;
const imgReq = sceneCount > 0
  ? `(${sceneCount}) 配图由外部场景方案(scene_plan)精确指定, 你**不需要**生成image_prompts, 返回空数组[]即可; 配图场景/标注内容不用你脑补`
  : `(5) ${p.num_images}张配图的英文prompt, 每张60词内, 描述具体场景+光线+构图, 覆盖不同角度/景别`;

// 有 scene_plan 时 sysPrompt 的 (5) 替换
let sysPrompt2 = sysPrompt;
if (sceneCount > 0) {
  sysPrompt2 = sysPrompt2.replace(/\(5\) \$\{p\.num_images\}张配图的英文prompt[^;]*;/, imgReq);
}

const chatBody = {
  model: 'Qwen3.6-35B-Hauhau',
  temperature: 0.85,
  max_tokens: 9000,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: sysPrompt2 },
    { role: 'user', content: userPrompt }
  ]
};
return [{ json: { chat_body: chatBody, num_images: effNum, scene_plan: scenePlanRaw, cover_indices: coverIdx, tg_chat_id: p.tg_chat_id, tg_bot_token: p.tg_bot_token, drafts_root: p.drafts_root, cover_url: p.cover_url, hot_count: (notes||[]).length }}];

const item = $input.first().json;
const seed = Math.floor(Math.random() * 1000000000);
// negative 按模式切换: 有标注(scene_plan)时只禁英文/乱码/外国人, 不禁中文标注; 无标注时全禁文字
const negNoText = 'text, letters, words, labels, captions, watermark, logo, checklist, table, spreadsheet, printed document, handwriting, typography, signage, tape labels, measurement marks, dimensions, numbers, ruler, scale markings, diagram, schematic, english text, english letters, alphabet, ascii, font, lettering, foreign person, white person, black person, western face';
const negLabelMode = item.negative_extra || 'english text, english letters, alphabet, ascii, font, lettering, watermark, logo, foreign person, white person, black person, western face, long paragraphs, sentence, paragraph text';
const negativeText = item.scene_plan_used ? negLabelMode : negNoText;
const workflow = {
  '1': {class_type:'UNETLoader', inputs:{unet_name:'qwen_image_fp8_e4m3fn.safetensors', weight_dtype:'default'}},
  '2': {class_type:'CLIPLoader', inputs:{clip_name:'qwen_2.5_vl_7b_fp8_scaled.safetensors', type:'qwen_image'}},
  '3': {class_type:'VAELoader', inputs:{vae_name:'qwen_image_vae.safetensors'}},
  '4': {class_type:'ModelSamplingAuraFlow', inputs:{model:['1',0], shift:3.1}},
  '5': {class_type:'CLIPTextEncode', inputs:{clip:['2',0], text:item.prompt}},
  '6': {class_type:'CLIPTextEncode', inputs:{clip:['2',0], text:negativeText}},
  '7': {class_type:'EmptySD3LatentImage', inputs:{width:1024, height:1024, batch_size:1}},
  '8': {class_type:'KSampler', inputs:{model:['4',0], positive:['5',0], negative:['6',0], latent_image:['7',0], seed, steps:20, cfg:2.5, sampler_name:'euler', scheduler:'simple', denoise:1.0}},
  '9': {class_type:'VAEDecode', inputs:{samples:['8',0], vae:['3',0]}},
  '10': {class_type:'SaveImage', inputs:{images:['9',0], filename_prefix:`n8n-xhs-${item.index}`}}
};
return [{ json: { comfy_body: { prompt: workflow, client_id: 'n8n' }, ...item }}];

const fs = require('fs');
const http = require('http');
const promptId = $input.first().json.prompt_id;
const prev = $('Build Comfy Workflow').item.json;
async function getJson(url) { return new Promise((res, rej) => http.get(url, r => { let d=''; r.on('data',c=>d+=c); r.on('end',()=>{try{res(JSON.parse(d))}catch(e){rej(e)}}); }).on('error', rej)); }
async function getBinary(url) { return new Promise((res, rej) => http.get(url, r => { const c=[]; r.on('data',b=>c.push(b)); r.on('end',()=>res(Buffer.concat(c))); }).on('error', rej)); }
const dl = Date.now() + 900000;
let result = null;
while (Date.now() < dl) {
  const d = await getJson(`http://127.0.0.1:8189/history/${promptId}`);
  if (d[promptId]) {
    const e = d[promptId], st = e.status || {};
    if (st.completed) {
      for (const nid in e.outputs || {}) {
        for (const img of (e.outputs[nid].images || [])) {
          const u = `http://127.0.0.1:8189/view?filename=${img.filename}&subfolder=${img.subfolder||''}&type=output`;
          const buf = await getBinary(u);
          const dest = `${prev.draft_dir}/img-${String(prev.index).padStart(2,'0')}-${img.filename}`;
          fs.writeFileSync(dest, buf);
          result = { saved: dest, filepath: dest };
          break;
        }
        if (result) break;
      }
      break;
    }
    if (st.status_str === 'error') { result = { error: 'workflow error' }; break; }
  }
  await new Promise(r => setTimeout(r, 3000));
}
if (!result) result = { error: 'timeout' };
return [{ json: { ...result, ...prev }}];

const fs = require('fs');
const dir = $('Keep First (dedup)').item.json.draft_dir;
const cover_url = $('Keep First (dedup)').item.json.cover_url || 'http://127.0.0.1:8765/cover';
const indices = $('Keep First (dedup)').item.json.cover_indices || [1];
// 生成封面 (host cover service), 支持多封面: indices=[1,7] → cover-1.png + cover-7.png
let coverPaths = [];
try {
  const http = require('http');
  const payload = JSON.stringify({ draft_dir: dir, sub: '装修干货', indices });
  const r = await new Promise((res, rej) => {
    const req = http.request({ host: '127.0.0.1', port: 8765, path: '/cover', method: 'POST', headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) }, timeout: 60000 }, resp => {
      let d = ''; resp.on('data', c => d += c); resp.on('end', () => { try { res(JSON.parse(d)) } catch(e) { rej(e) } });
    });
    req.on('error', rej); req.on('timeout', () => { req.destroy(); rej(new Error('cover timeout')); });
    req.write(payload); req.end();
  });
  coverPaths = (r.cover_paths || []).filter(p => fs.existsSync(p));
} catch (e) { console.log('cover gen failed:', e.message); }

const files = fs.readdirSync(dir).filter(f => f.startsWith('img-')).sort();
const prev = $('Parse + Save (single)').first().json;
const md = fs.readFileSync(`${dir}/note.md`, 'utf8');
return [{ json: { ...prev, draft_dir: dir, images: files, cover_paths: coverPaths, cover_path: coverPaths[0] || '', md_text: md } }];

