const fs = require('fs');
// 跨节点引用: cover_paths/cover_path/images/draft_dir 在 Prep TG + Cover 输出里
const p = $('Prep TG + Cover').first().json;
const files = [];
// 所有封面 (支持多封面: cover_paths)
const covers = (p.cover_paths || []).filter(cp => fs.existsSync(cp));
for (const cp of covers) files.push(cp);
// 正文图: 跳过被用作封面的配图 (cover_indices)
const coverIdx = new Set((p.cover_indices || [1]).map(i => String(i).padStart(2, '0')));
for (const f of (p.images || [])) {
  const m = f.match(/^img-(\d+)/);
  const num = m ? m[1] : '';
  if (num && coverIdx.has(num)) continue;  // 这张已被封面用, 不重复推
  files.push(`${p.draft_dir}/${f}`);
}
return files.map((fp, i) => ({
  json: { filename: fp.split('/').pop(), filepath: fp, tg_chat_id: p.tg_chat_id, tg_bot_token: p.tg_bot_token },
  binary: { data: { data: fs.readFileSync(fp).toString('base64'), mimeType: 'image/png', fileName: fp.split('/').pop() } }
}));

const fs = require('fs');
const http = require('http');
const raw = $input.first().json.choices[0].message.content;
let data = {};
for (let i = 0; i < 3; i++) {
  try { data = JSON.parse(raw); break; } catch (e) { const m = raw.match(/{[\s\S]*}/); if (m) raw = m[0]; else throw new Error('bad json from hauhau: ' + raw.slice(0,200)); }
}
const prev = $('Build Hauhau Prompt').item.json;

// 手动解析 url (沙箱无 URL 全局)
function parseUrl(url) {
  const m = url.match(/^https?:\/\/([^:\/]+)(?::(\d+))?([^?]*)/);
  if (!m) throw new Error('bad url: ' + url);
  return { hostname: m[1], port: m[2] ? parseInt(m[2]) : 80, path: m[3] || '/' };
}
function post(url, body, timeout) {
  return new Promise((res, rej) => {
    const u = parseUrl(url);
    const payload = JSON.stringify(body);
    const req = http.request({ hostname: u.hostname, port: u.port, path: u.path, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) }, timeout: timeout||180000 }, r => {
      let d = ''; r.on('data', c => d += c); r.on('end', () => { try { res(JSON.parse(d)); } catch(e) { rej(e); } });
    });
    req.on('error', rej); req.on('timeout', () => { req.destroy(); rej(new Error('timeout')); });
    req.write(payload); req.end();
  });
}

async function verify(d) {
  const content = '标题: ' + (d.title||'') + '\n正文: ' + (d.body||'').slice(0, 900) + '\n标签: ' + (d.tags||[]).join(' ');
  const r = await post('http://127.0.0.1:8083/v1/chat/completions', {
    model: 'Qwen2.5-VL-7B', temperature: 0.1, max_tokens: 80, response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: '你是小红书文案贴合度校验器。判断给定文案是否属于「家居家装/装修干货」垂类且贴合账号「宅有宅的道理」的装修干货定位。若核心是装修/软装/收纳/改造方法, 返回 {"fit":true,"reason":"..."}; 若偏到其他垂类(美妆/母婴/数码/穿搭/美食等), 返回 {"fit":false,"reason":"..."}。严格只返回JSON' },
      { role: 'user', content }
    ]
  });
  const c = (r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '{}';
  let p = {}; try { p = JSON.parse(c); } catch(e) { const m = c.match(/{[\s\S]*}/); if (m) { try { p = JSON.parse(m[0]); } catch(_) {} } }
  return { fit: p.fit === true, reason: (p.reason || '').slice(0, 200) };
}

let v = await verify(data);
let retried = false;
if (!v.fit) {
  retried = true;
  const retryPrompt = '上次生成的文案偏离了「家居家装/装修干货」垂类。' + v.reason + '\n请重新创作一篇严格围绕装修/软装/收纳干货的文案(风格不限, 中古风/奶油风/原木风/现代极简都可以), 保留: 标题15字内带emoji, 正文250-600字短句多段, 8-10个中文tag, ' + prev.num_images + '张配图英文prompt。\n上次文案(参考不要照抄): 标题=' + (data.title||'') + ' 正文=' + (data.body||'').slice(0,400) + '\n严格返回JSON {"title","body","tags","image_prompts"}';
  const rr = await post('http://127.0.0.1:8080/v1/chat/completions', {
    model: 'Qwen3.6-35B-Hauhau', temperature: 0.8, max_tokens: 9000, response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: '你是专业的小红书爆款文案师, 账号「宅有宅的道理」家居装修干货号。严格返回JSON {"title","body","tags","image_prompts"}。正文不许出现#开头行, tag只在tags数组。' },
      { role: 'user', content: retryPrompt }
    ]
  }, 180000);
  const raw2 = (rr.choices && rr.choices[0].message.content) || '';
  let d2 = {}; for (let i = 0; i < 3; i++) { try { d2 = JSON.parse(raw2); break; } catch(e) { const m = raw2.match(/{[\s\S]*}/); if (m) raw2 = m[0]; else break; } }
  if (d2.title) { data = d2; v = await verify(d2); }
}
return [{ json: { ...prev, data, fit: v.fit, fit_reason: v.reason, retried } }];

const fs = require('fs');
const p = $input.first().json;
const d = p.data || {};
const body = (d.body || '').split('\n').filter(l => !/^\s*#+\s*[\u4e00-\u9fa5]/.test(l)).join('\n').replace(/\n{3,}/g, '\n\n').trim();
const tagsClean = [...new Set((d.tags || []).map(t => t.replace(/^#+/, '').trim()).filter(Boolean))];
const ts = new Date().toISOString().slice(0,19).replace(/[-:T]/g,'');
const draftDir = `${p.drafts_root}/${ts}`;
fs.mkdirSync(draftDir, { recursive: true });
const md = `# ${d.title}\n\n${body}\n\n${tagsClean.map(t=>'#'+t).join(' ')}\n\n---\n_基于 ${p.hot_count} 篇热榜笔记提炼生成${p.retried ? ' (自动重写1次)' : ''}_\n`;
fs.writeFileSync(`${draftDir}/note.md`, md);

// ===== scene_plan 支持: 有 scene_plan 时配图 prompt 由方案精确构造, 覆盖 hauhau 脑补的 =====
let imagePrompts = d.image_prompts || [];
let styleTag = 'label-diagram';
let negExtra = 'english text, letters, alphabet, ascii, font, lettering, watermark, logo, foreign person, white person, black person, western face';
let scenePlanUsed = false;
let scenePlan = null;
if (p.scene_plan && typeof p.scene_plan === 'string') {
  try { scenePlan = JSON.parse(p.scene_plan); } catch(e) { console.log('scene_plan parse err', e.message); }
} else if (p.scene_plan && typeof p.scene_plan === 'object') {
  scenePlan = p.scene_plan;
}
if (scenePlan && Array.isArray(scenePlan.images) && scenePlan.images.length > 0) {
  scenePlanUsed = true;
  if (scenePlan.style_prefix) {
    imagePrompts = scenePlan.images.map(img => {
      const labelStr = (img.labels || []).join('; ');
      // 标注图: 英文场景 + 中文标注要求
      return `${scenePlan.style_prefix} ${img.scene} Chinese annotation labels: rectangular white label boxes with thin dark border, connected by thin dashed lines to each device point, text in Chinese short words only (e.g. ${labelStr}), height numbers in cm, labels large clear legible, no other text.`;
    });
  } else {
    imagePrompts = scenePlan.images.map(img => img.scene || '');
  }
  if (scenePlan.negative_extra) negExtra = scenePlan.negative_extra;
  if (scenePlan.style) styleTag = scenePlan.style;
}

return [{ json: {
  draft_id: ts, draft_dir: draftDir, title: d.title, body: body, tags: tagsClean,
  image_prompts: imagePrompts, num_images: scenePlanUsed ? imagePrompts.length : p.num_images,
  scene_plan_used: scenePlanUsed, style_tag: styleTag, negative_extra: negExtra,
  hot_count: p.hot_count, tg_chat_id: p.tg_chat_id, tg_bot_token: p.tg_bot_token,
  cover_url: p.cover_url, drafts_root: p.drafts_root, cover_indices: p.cover_indices || [1],
  fit: p.fit, fit_reason: p.fit_reason, retried: p.retried
}}];

const p = $input.first().json;
const badge = p.retried ? ' [已自动重写]' : '';
const full = '

' + p.title + '

' + (p.body||'') + '

' + (p.tags||[]).map(t=>'#'+t).join(' ');
return [{ json: { ...p,
  preview_text: '📝 文案草稿' + badge + ' (' + (p.fit ? '通过校验' : '可能偏题') + ')

' + p.title + '

' + (p.body||'') + '

' + (p.tags||[]).map(t=>'#'+t).join(' ') + '

📄 完整文件: ' + (p.draft_dir||'') + '/note.md'
}}];

const fs = require('fs');
const http = require('http');
// Wait resume 后 $input 是 {ok, result} 包装, 从 A1 跨节点取真实数据
const p = $('A1 Prep Preview').item.json;
const decisionPath = `${p.draft_dir}/decision.json`;
let action = 'approve';
let reason = '';
try {
  if (fs.existsSync(decisionPath)) {
    const dec = JSON.parse(fs.readFileSync(decisionPath, 'utf8'));
    action = dec.action || 'approve';
    reason = dec.reason || '';
  }
} catch(e) { console.log('decision read err', e.message); }

let finalTitle = p.title, finalBody = p.body, finalTags = p.tags, finalPrompts = p.image_prompts || [];
let rewrote = false;
if (action === 'rewrite') {
  try {
    const payload = JSON.stringify({
      model: 'Qwen3.6-35B-Hauhau', temperature: 0.8, max_tokens: 9000, response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: '你是专业的小红书爆款文案师, 账号「宅有宅的道理」家居装修干货号。严格返回JSON {"title","body","tags","image_prompts"}。正文不许出现#开头行, tag只在tags数组。' },
        { role: 'user', content: '用户要求重写这篇文案。' + reason + '\n请围绕装修/软装/收纳干货重新创作(风格不限), 标题15字内带emoji, 正文250-600字, 8-10个中文tag, ' + p.num_images + '张配图英文prompt。\n原稿(参考不要照抄): 标题=' + p.title + ' 正文=' + (p.body||'').slice(0,400) + '\n严格返回JSON {"title","body","tags","image_prompts"}' }
      ]
    });
    const rr = await new Promise((res, rej) => {
      const req = http.request({ hostname: '127.0.0.1', port: 8080, path: '/v1/chat/completions', method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) }, timeout: 180000 }, r => {
        let d = ''; r.on('data', c => d += c); r.on('end', () => { try { res(JSON.parse(d)); } catch(e) { rej(e); } });
      });
      req.on('error', rej); req.on('timeout', () => { req.destroy(); rej(new Error('timeout')); });
      req.write(payload); req.end();
    });
    const raw2 = (rr.choices && rr.choices[0].message.content) || '';
    let d2 = {}; for (let i = 0; i < 3; i++) { try { d2 = JSON.parse(raw2); break; } catch(e) { const m = raw2.match(/{[\s\S]*}/); if (m) raw2 = m[0]; else break; } }
    if (d2.title) {
      finalTitle = d2.title; finalBody = (d2.body||'').split('\n').filter(l => !/^\s*#+\s*[\u4e00-\u9fa5]/.test(l)).join('\n').replace(/\n{3,}/g,'\n\n').trim();
      finalTags = [...new Set((d2.tags||[]).map(t=>t.replace(/^#+/,'').trim()).filter(Boolean))];
      // scene_plan 时配图由方案精确构造, 不用 hauhau 重写生成的
      let sp = null;
      try { sp = JSON.parse(p.scene_plan); } catch(e) {}
      if (sp && Array.isArray(sp.images) && sp.images.length > 0) {
        finalPrompts = sp.images.map(img => {
          const labelStr = (img.labels || []).join('; ');
          return `${sp.style_prefix || ''} ${img.scene} Chinese annotation labels: rectangular white label boxes with thin dark border, connected by thin dashed lines to each device point, text in Chinese short words only (e.g. ${labelStr}), height numbers in cm, labels large clear legible, no other text.`;
        });
      } else {
        finalPrompts = d2.image_prompts || [];
      }
      rewrote = true;
      const md = `# ${finalTitle}\n\n${finalBody}\n\n${finalTags.map(t=>'#'+t).join(' ')}\n\n---\n_用户要求重写 (${new Date().toISOString().slice(0,19)})_\n`;
      fs.writeFileSync(`${p.draft_dir}/note.md`, md);
    }
  } catch(e) { console.log('rewrite err', e.message); }
}

const n = finalPrompts.length > 0 ? finalPrompts.length : p.num_images;
const result = [];
for (let i = 0; i < n; i++) {
  result.push({ json: { prompt: finalPrompts[i] || '', index: i + 1, total: n, draft_dir: p.draft_dir, md_path: `${p.draft_dir}/note.md`, title: finalTitle, body: finalBody, tags: finalTags, hot_count: p.hot_count, tg_chat_id: p.tg_chat_id, tg_bot_token: p.tg_bot_token, cover_url: p.cover_url, draft_id: p.draft_id, decision: action, rewrote, scene_plan_used: !!p.scene_plan, negative_extra: p.negative_extra || '', cover_indices: p.cover_indices || [1] } });
}
return result;
